sysevent_script_action.script:
try {
    var createSwiftOnDemand = new GlideRecord('x_hsb11_mss_c_swft_mss_custody_swift_ondemand_staging');
    createSwiftOnDemand.initialize();
    if (current.sys_class_name == "x_hsb11_mss_c_proc_mss_custody_trade") {
        createSwiftOnDemand.request_body = 'hsbcTransactionIdentification=' + encodeURIComponent(current.trade_id) + '&messageProcessingStatus=completed';
        createSwiftOnDemand.trade_reference = current.sys_id;

    } else if (current.sys_class_name == "x_hsb11_mss_c_proc_mss_custody_task") {
        //MSSCUSTODY-6483 
        createSwiftOnDemand.request_body = 'hsbcTransactionIdentification=' + encodeURIComponent(current.trade_id.trade_id) + '&messageProcessingStatus=completed';
        createSwiftOnDemand.task_reference = current.sys_id;
        createSwiftOnDemand.trade_reference = current.trade_id;
    }
    createSwiftOnDemand.state = 'Ready to be sent';
    createSwiftOnDemand.trade_type = "Completed";
    createSwiftOnDemand.request_date = new GlideDateTime();
    createSwiftOnDemand.insert();
} catch (e) {
    gs.info("The issue is" + e);
}
